package com.dixitdada.journalApp.service; import com.dixitdada.journalApp.api.response.WeatherResponse; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; @Service public class WeatherService { private final RestClient client=RestClient.create(); public WeatherResponse current(double lat,double lon){String u="https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,wind_speed_10m";return client.get().uri(u).retrieve().body(WeatherResponse.class);} }